const tools = parseTools($input.first().json);
const target = tools.length > 0 ? tools[0] : null;
if (!target) {
  return [{ json: { skipped: true, reason: "No tool available to probe." } }];
}
return [{ json: { toolName: target.name, fuzzLabel: "Unrecognized argument key probe", fuzzValue: "probe" } }];

const items = $input.all();

if (items.length === 1 && items[0].json.skipped) {
  return [{ json: { summary: `Argument fuzzing skipped: ${items[0].json.reason}` } }];
}

const leakPatterns = [
  /at\s+Object\.\w+\s*\(/,
  /Traceback \(most recent call last\)/,
  /\/usr\/[\w\/.-]+/,
  /\/home\/[\w\/.-]+/,
  /[A-Za-z]:\\[\w\\.-]+/,
  /SyntaxError|TypeError|ReferenceError/,
  /SQLSTATE|ORA-\d+|SQL syntax/i
];

const leaks = [];
const crashes = [];
for (const item of items) {
  const json = item.json;
  const isConnectionFailure = !!(json.error && /aborted|offline|ECONNRESET|socket hang up|timeout/i.test(JSON.stringify(json.error)));
  if (isConnectionFailure) {
    crashes.push(`sending '${json.fuzzLabel || "an unrecognized argument"}' to '${json.toolName || "a tool"}' caused the connection to hang/abort (confirmed live, 5s timeout) rather than a clean error response`);
    continue;
  }
  const raw = JSON.stringify(json);
  const leaked = leakPatterns.some(p => p.test(raw));
  if (leaked) {
    leaks.push(`sending '${json.fuzzLabel || "unexpected input"}' triggered a response resembling an internal error/stack trace/path`);
  }
}

const parts = [];
if (crashes.length > 0) {
  parts.push(`FUZZ TEST CRASH (confirmed live): ${crashes.join("; ")} — an unhandled exception or crash on malformed input can indicate a denial-of-service vector or missing input validation.`);
}
if (leaks.length > 0) {
  parts.push(`FUZZ TEST LEAK: ${leaks.join("; ")} — investigate for information disclosure.`);
}

const summary = parts.length > 0
  ? parts.join(" ")
  : "Argument fuzzing (single live probe with an unrecognized argument key) completed cleanly — no hang, stack trace, or leak observed this run.";

return [{ json: { summary } }];

