const tools = parseTools($input.first().json);

const sensitiveKeywords = ["token", "key", "secret", "credential", "session", "password", "config", "env", "user"];
const producers = tools.filter(t => sensitiveKeywords.some(k => (t.description || "").toLowerCase().includes(k) || (t.name || "").toLowerCase().includes(k)));

const chains = [];
for (const producer of producers) {
  for (const consumer of tools) {
    if (consumer.name === producer.name) continue;
    const consumerSchemaStr = JSON.stringify(consumer.inputSchema || {}).toLowerCase();
    const matchesField = sensitiveKeywords.some(k => consumerSchemaStr.includes(k));
    if (matchesField) {
      chains.push(`'${producer.name}' may expose sensitive data that '${consumer.name}' accepts as input`);
    }
  }
}

const summary = chains.length > 0
  ? `TOOL CHAINING RISK: ${chains.join("; ")} — potential confused-deputy/privilege-escalation chain worth manual review.`
  : `No obvious tool-chaining/confused-deputy risk identified from static analysis of the ${tools.length} tool(s) on this target — no tool appears to both expose sensitive-sounding data and accept a matching sensitive-sounding input elsewhere.`;

return [{ json: { summary } }];

