return [{ json: { fingerprintTool: target } }];

function parseCallResult(raw) {
  try {
    const match = (raw || "").match(/data:\s*(\{.*\})/);
    if (match) {
      const outer = JSON.parse(match[1]);
      return outer.result || outer.error || null;
    }
  } catch (e) {}
  return null;
}

const r1 = parseCallResult($('Fingerprint Call 1').first().json.data);
const r2 = parseCallResult($('Fingerprint Call 2').first().json.data);
const r3 = parseCallResult($('Fingerprint Call 3').first().json.data);

function structureKey(obj) {
  if (!obj || typeof obj !== "object") return typeof obj;
  if (Array.isArray(obj)) return `array(${obj.length ? structureKey(obj[0]) : "empty"})`;
  return Object.keys(obj).sort().map(k => `${k}:${typeof obj[k]}`).join(",");
}

const tool = $('Pick Fingerprint Target').first().json.fingerprintTool;
if (!tool) {
  return [{ json: { summary: "Behavioral fingerprinting skipped: no tool available to test." } }];
}

const structures = [structureKey(r1), structureKey(r2), structureKey(r3)];
const consistent = structures.every(s => s === structures[0]);

const summary = consistent
  ? `Behavioral fingerprint: calling '${tool}' three times returned a consistent response structure each time — no signs of hidden conditional/non-deterministic behavior.`
  : `BEHAVIORAL INCONSISTENCY: calling '${tool}' three times returned DIFFERENT response structures across calls — this can indicate hidden conditional logic, caller-dependent behavior, or an unstable/unreliable tool implementation. Investigate further.`;

return [{ json: { summary } }];

const raw = $input.first().json.output || "";
let payloads = [];
try {
  const cleaned = raw.trim().replace(/^```json\s*/i, "").replace(/```$/, "").trim();
  payloads = JSON.parse(cleaned);
} catch (e) {
  payloads = [];
}
if (!Array.isArray(payloads)) payloads = [];
return payloads
  .filter(p => p && p.payload && p.expectedTool)
  .map(p => ({ json: { payload: p.payload, expectedTool: p.expectedTool, source: "adversarial-ai-generated" } }));

const currentItem = $input.first().json;
const findings = (currentItem.currentFindings || [])
  .map(f => f.summary)
  .filter(Boolean);

return [{ json: { combinedFindings: findings.join("\n\n") } }];

const items = $input.all();
const targetItem = items.find(i => i.json.target_url && i.json.status === "authorized");
const findingsItem = items.find(i => Array.isArray(i.json.currentFindings));

const targetUrl = targetItem?.json.target_url || "unknown";
const findings = (findingsItem?.json.currentFindings || []).map(f => f.summary).filter(Boolean);
const now = new Date().toISOString();

return findings.map(summary => ({
  json: { target_url: targetUrl, scanned_at: now, finding_summary: summary }
}));
